import re
from decimal import Context, Decimal, DecimalException, Inexact, InvalidOperation


_AMOUNT_PATTERN = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")
_MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")


def parse_amount(value):
    if isinstance(value, bool):
        raise ValueError("Invalid amount type")
    if isinstance(value, str):
        if _AMOUNT_PATTERN.fullmatch(value) is None:
            raise ValueError("Invalid amount string")
        amount = Decimal(value)
    elif isinstance(value, (Decimal, int)):
        amount = Decimal(value)
    else:
        raise ValueError("Invalid amount type")

    if not amount.is_finite() or amount <= 0 or amount > _MAX_AMOUNT:
        raise ValueError("Amount must be positive and at most 1000000.00")

    # Nine digits cover the maximum amount in cents. An independent context
    # keeps caller precision/traps unchanged; Inexact forbids fractional cents
    # while allowing discarded trailing zeros.
    context = Context(prec=9, traps=[Inexact, InvalidOperation])
    try:
        return amount.quantize(_CENT, context=context)
    except DecimalException as exc:
        raise ValueError("Amount must be exactly representable in cents") from exc


def format_amount(value):
    return format(value, ".2f")
